// Generated by scripts/sync-film.mjs from motion-film/src/kit/Dual.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { fonts } from "../theme/fonts";
import type { Bi } from "../data/i18n";

/**
 * Hindi above, English beneath. The Hindi keeps the given style; the English companion is set
 * in Cormorant italic at `enScale` of the size, slightly softer, so hierarchy stays clear.
 */
export const Dual: React.FC<{
  text: Bi;
  style?: React.CSSProperties;
  enStyle?: React.CSSProperties;
  enScale?: number;
  gap?: number;
  align?: "center" | "left" | "right";
}> = ({ text, style, enStyle, enScale = 0.52, gap = 2, align = "center" }) => {
  const size = typeof style?.fontSize === "number" ? style.fontSize : 32;
  const showEn = text.en && text.en !== text.hi;
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: align === "center" ? "center" : align === "left" ? "flex-start" : "flex-end", textAlign: align }}>
      <div style={{ ...style, lineHeight: Math.max(1.25, Number(style?.lineHeight ?? 1.25)), fontStyle: "normal" }}>{text.hi}</div>
      {showEn ? (
        <div
          style={{
            fontFamily: fonts.latin,
            fontStyle: "italic",
            fontWeight: 500,
            fontSize: Math.max(18, size * enScale),
            lineHeight: 1.15,
            color: style?.color,
            opacity: 0.82,
            marginTop: gap,
            ...enStyle,
          }}
        >
          {text.en}
        </div>
      ) : null}
    </div>
  );
};
